export function themeCSS(name = ACTIVE_THEME) {
  const theme = THEMES[name] || THEMES.console;
  return '/* Hallmark: shared app screen, modern-minimal, swappable Console/Coral/Dose */\n/* Critique: real records, exact approvals, bounded evidence, responsive stages */\n' + theme.fonts + '\n[data-theme="' + name + '"] {' + theme.tokens + ';\n}\n.chalkline-ui {' + shared + '\n' + theme.overrides + '\n}';
}

